import { describe, expect, test } from "bun:test";

describe("CLI", () => {
  test("renders files to stdout without extra output", async () => {
    const process = Bun.spawn({
      cmd: [
        Bun.which("bun")!,
        "run",
        "src/cli.ts",
        "test/fixtures/template.txt",
        "test/fixtures/data.json",
      ],
      stdout: "pipe",
      stderr: "pipe",
    });
